export class Product {
  id?: string; // Add optional ID field
  brandName: string;
  name: string;
  price: string;
  originalPrice?: string; // Add optional originalPrice field
  imageLink: string;
  gallery?: string[]; // Add optional gallery field
  detailLink: string;
  description: string;
  category?: string; // Add optional category field
  inStock?: boolean; // Add optional inStock field
  rating?: number; // Add optional rating field
  reviewCount?: number; // Add optional reviewCount field
  features?: string[]; // Add optional features field
  quantity?: number; // Add optional quantity field for cart

  constructor(
    brandName: string = '',
    name: string = '',
    price: string = '',
    imageLink: string = '',
    detailLink: string = '',
    description: string = '',
    id?: string,
    originalPrice?: string,
    gallery?: string[],
    category?: string,
    inStock?: boolean,
    rating?: number,
    reviewCount?: number,
    features?: string[],
    quantity?: number
  ) {
    this.brandName = brandName;
    this.name = name;
    this.price = price;
    this.imageLink = imageLink;
    this.detailLink = detailLink;
    this.description = description;
    this.id = id || name; // Use name as ID if no ID provided
    this.originalPrice = originalPrice;
    this.gallery = gallery;
    this.category = category;
    this.inStock = inStock;
    this.rating = rating;
    this.reviewCount = reviewCount;
    this.features = features;
    this.quantity = quantity;
  }
}

// Interface matching the exact API response
export interface ProductApiResponse {
  code: number;
  message: string;
  data: Product[];
}
